def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]

    # Exploit mode: in last 3 rounds, we defected at least twice, opponent cooperated all three.
    if n >= 3:
        last3_my = my_moves[-3:]
        last3_opp = opp_moves[-3:]
        if last3_my.count('D') >= 2 and last3_opp.count('C') == 3:
            return 'D'

    last_my, last_opp = history[-1]
    if n >= 2:
        prev_my, prev_opp = history[-2]
    else:
        prev_my, prev_opp = None, None

    if last_opp == 'C':
        if last_my == 'D':
            # We defected last round, opponent cooperated. Not in exploit mode, so apologize.
            return 'C'
        else:  # last_my == 'C'
            # Mutual cooperation
            # If we just had a successful probe (we defected two rounds ago, opponent cooperated, and last round both cooperated)
            if prev_my == 'D' and prev_opp == 'C':
                return 'D'  # start exploiting
            # Consider probing
            if n >= 5:
                if my_moves[-5:].count('C') == 5 and opp_moves[-5:].count('C') == 5:
                    # Probe occasionally
                    if n % 10 == 0:
                        # Check historical retaliation to avoid probing punitive opponents too often
                        my_def = 0
                        retal = 0
                        for i in range(n-1):
                            if my_moves[i] == 'D':
                                my_def += 1
                                if opp_moves[i+1] == 'D':
                                    retal += 1
                        if my_def >= 2 and retal >= my_def // 2:
                            if n % 20 == 0:
                                return 'D'
                        else:
                            return 'D'
            return 'C'

    else:  # last_opp == 'D'
        if last_my == 'D':
            # We are in DD. If we were exploiting (prev round was D,C), apologize now.
            if n >= 2 and history[-2][1] == 'C' and history[-2][0] == 'D':
                return 'C'
            # Otherwise, try to break out of mutual defection if opponent has cooperated before.
            if opp_moves.count('C') > 0:
                dd_streak = 0
                for i in range(n-1, -1, -1):
                    if my_moves[i] == 'D' and opp_moves[i] == 'D':
                        dd_streak += 1
                    else:
                        break
                if dd_streak >= 3 and rng.random() < 0.3:
                    return 'C'
            return 'D'
        else:  # last_my == 'C'
            # We cooperated, opponent defected.
            # If we defected two rounds ago, this is retaliation -> apologize.
            if prev_my == 'D':
                return 'C'
            else:
                # Opponent exploiting us -> retaliate
                return 'D'
